// Offline V1→V2 env translation for `evolver migrate env` (Refs #698).
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { bootstrap } from '@evomap/evolver-core';
import { expandHomePath, parseEnvFile } from '@evomap/evolver-mcp';
function loadFileEnv(path) {
    const resolved = resolve(expandHomePath(path));
    return parseEnvFile(readFileSync(resolved, 'utf8'));
}
export function runMigrateEnvScan(opts, processEnv = process.env) {
    let env = {};
    let source = 'process';
    if (opts.file) {
        const fromFile = loadFileEnv(opts.file);
        env = { ...fromFile };
        source = 'file';
        if (opts.includeProcessEnv !== false) {
            env = { ...processEnv, ...fromFile };
            source = 'file+process';
        }
    }
    else {
        env = { ...processEnv };
    }
    const report = bootstrap.translateV1Env(env);
    return { report, scannedKeys: Object.keys(env).sort(), source };
}
/** Build a dotenv fragment for mappable keys only (never writes secret values for keep/GITHUB). */
export function formatMappedDotenvFragment(report) {
    const lines = [
        '# Generated by: evolver migrate env --write-suggestions',
        '# Only MAP suggestions (V1 → V2 rename). Review before applying.',
        '# Manual and removed V1 keys are comments; resolve manual items before deleting them.',
        ...(report.caveats ?? []).map((caveat) => `# CAVEAT ${caveat}`),
        '',
    ];
    for (const s of report.suggestions) {
        if (s.action === 'map' && s.v2Name && s.v2Value !== undefined) {
            lines.push(`# was ${s.v1Name}`);
            lines.push(`${s.v2Name}=${JSON.stringify(s.v2Value)}`);
            lines.push('');
        }
        else if (s.action === 'manual') {
            lines.push(`# REVIEW ${s.v1Name} — ${s.guidance}`);
            lines.push('');
        }
        else if (s.action === 'remove') {
            lines.push(`# REMOVE ${s.v1Name} — ${s.guidance}`);
            lines.push('');
        }
    }
    return lines.join('\n');
}
export function parseMigrateEnvArgs(argv) {
    const opts = {};
    for (let i = 0; i < argv.length; i += 1) {
        const a = argv[i] ?? '';
        if (a === '--json')
            opts.json = true;
        else if (a === '--file' || a === '--env-file') {
            const v = argv[++i];
            if (!v || v.startsWith('--'))
                return { error: 'migrate env --file requires a path' };
            opts.file = v;
        }
        else if (a.startsWith('--file='))
            opts.file = a.slice('--file='.length);
        else if (a.startsWith('--env-file='))
            opts.file = a.slice('--env-file='.length);
        else if (a === '--write-suggestions') {
            const v = argv[++i];
            if (!v || v.startsWith('--'))
                return { error: 'migrate env --write-suggestions requires a path' };
            opts.writeSuggestions = v;
        }
        else if (a.startsWith('--write-suggestions='))
            opts.writeSuggestions = a.slice('--write-suggestions='.length);
        else if (a === '--no-process-env')
            opts.includeProcessEnv = false;
        else if (a === '--help' || a === '-h')
            return { error: 'help' };
        else
            return { error: `unknown argument: ${a}` };
    }
    return opts;
}
export async function runMigrateEnvCommand(argv, io = {}) {
    const stdout = io.stdout ?? ((line) => { process.stdout.write(line); });
    const stderr = io.stderr ?? ((line) => { process.stderr.write(line); });
    const usage = [
        'Usage: evolver migrate env [--file <dotenv>] [--json] [--write-suggestions <path>] [--no-process-env]',
        '',
        'Offline V1→V2 env translation for knobs removed or renamed after upgrade (Refs #698).',
        'Does not load secrets into resolvers; prints key names and actions only in text mode.',
        '',
    ].join('\n');
    const parsed = parseMigrateEnvArgs(argv);
    if ('error' in parsed) {
        if (parsed.error === 'help') {
            stdout(usage);
            return 0;
        }
        stderr(`${parsed.error}\n${usage}`);
        return 1;
    }
    try {
        const result = runMigrateEnvScan(parsed, io.env ?? process.env);
        if (parsed.writeSuggestions) {
            const fragment = formatMappedDotenvFragment(result.report);
            writeFileSync(resolve(expandHomePath(parsed.writeSuggestions)), fragment, {
                encoding: 'utf8',
                flag: 'wx',
                mode: 0o600,
            });
        }
        if (parsed.json) {
            // JSON mode deliberately emits metadata only; raw source and mapped values stay in memory.
            const safe = {
                source: result.source,
                detectedCount: result.report.detectedCount,
                mappableCount: result.report.mappableCount,
                manualCount: result.report.manualCount,
                removableCount: result.report.removableCount,
                githubTokenPresent: result.report.githubTokenPresent,
                caveats: result.report.caveats ?? [],
                suggestions: result.report.suggestions.map((s) => ({
                    v1Name: s.v1Name,
                    action: s.action,
                    v2Name: s.v2Name,
                    guidance: s.guidance,
                })),
            };
            stdout(`${JSON.stringify(safe, null, 2)}\n`);
        }
        else {
            stdout(bootstrap.formatV1EnvTranslationReport(result.report));
            if (parsed.writeSuggestions) {
                stdout(`wrote suggestions: ${parsed.writeSuggestions}\n`);
            }
        }
        return 0;
    }
    catch (error) {
        stderr(`migrate env: ${error instanceof Error ? error.message : String(error)}\n`);
        return 1;
    }
}